parameters.jsCode:
const clusters = {};

for (const item of items) {
  const text = (
    (item.json.title || "") + " " + (item.json.description || "")
  ).toLowerCase();

  let key = "General Procurement";

  if (text.includes("supplier") || text.includes("vendor")) {
    key = "Supplier Management";
  } else if (text.includes("invoice") || text.includes("payment")) {
    key = "Invoice Processing";
  } else if (text.includes("contract")) {
    key = "Contract Management";
  } else if (text.includes("purchase")) {
    key = "Purchasing";
  }

  if (!clusters[key]) {
    clusters[key] = [];
  }

  clusters[key].push(item.json);
}

return Object.entries(clusters).map(([topic, data]) => ({
  json: {
    topic,
    issues: data
  }
}));

return items.map(item => {
  const issues = (item.json.issues || []).slice(0, 5);

  const issue_summary = issues
    .map(i => `${i.title || i.name || "Untitled"} - ${i.description || i.body || "No description"}`)
    .join("\n");

  return {
    json: {
      topic: item.json.topic,
      issue_summary
    }
  };
});

