parameters.jsCode:
return items.map(item => {
  try {
    const raw = String(
      item.json.output ||
      item.json.text ||
      item.json.response ||
      ""
    )
      .replace(/```json/g, "")
      .replace(/```/g, "")
      .trim();

    const parsed = JSON.parse(raw);

    return {
      json: {
        root_cause: parsed.root_cause || "",
        problem: parsed.problem || "",
        resolution: parsed.resolution || "",
        title: parsed.title || ""
      }
    };

  } catch (error) {
    return {
      json: {
        root_cause: "Not determined",
        problem: "Not determined",
        resolution: "Not determined",
        title: "Untitled Procurement Issue"
      }
    };
  }
});
